def lstm_outputs(n_steps, units, return_sequences):
    per_step = [[0.0] * units for _ in range(n_steps)]
    if return_sequences:
        return per_step            # shape (T, units)
    return per_step[-1]            # shape (units,)

seq = lstm_outputs(12, 16, return_sequences=True)
print('return_sequences=True  ->', len(seq), 'timesteps x', len(seq[0]), 'units')
last = lstm_outputs(12, 16, return_sequences=False)
print('return_sequences=False -> just', len(last), 'values (last timestep)')
print('a following Dense(4) acts on the LAST axis: (batch, 12, 16) -> (batch, 12, 4)')
